],
"proposal": {
  "capability": "deployment.set-probes",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "finance",
    "name": "ledger",
    "uid": "uid-deployment-ledger"
  },
  "params": {
    "container": "app",
    "liveness": {
      "timeoutSeconds": 5
    }
  },
  "expected_effect": "Increase the liveness probe timeout to 5s, allowing the app to respond after starting.",
  "rationale": "The liveness probe's timeout is 1s, which is too short for the app to respond after starting. The logs show the app was still initializing and hadn't started the HTTP server when the probe timed out. Increasing the timeout to 5s will allow the app to respond before the probe fails.",
  "cited_evidence_ids": ["ev-rollout_history", "ev-pod_states", "ev-target_events", "ev-container_logs_tail"],
  "cited_predicates": ["probe_kills", "killed_during_startup", "rollout_changed_the_app"]
}
